-- 1. Alaro Cycling Club - Cycling Club in Mallorca
INSERT INTO businesses (name, slug, shortDescription, description, sportCategoryId, businessTypeId, city, country, region, hub, website, approvalStatus, isActive, isFeatured)
VALUES ('Alaró Cycling Club', 'alaro-cycling-club', 'Cycling training camps in Alaró, Mallorca with professional coaching and hospitality.', 'Alaró Cycling Club offers cycling training camps in Alaró, Mallorca, providing a combination of professional coaching, hospitality, and a welcoming atmosphere for cyclists of all levels. Their camps combine structured training with the stunning routes of the Serra de Tramuntana mountains.', 1, 6, 'Alaró', 'Spain', 'Mallorca', 'Alaró', 'https://www.alarocyclingclub.com/en', 'approved', true, false);

