INSERT INTO businesses (name, slug, shortDescription, description, sportCategoryId, businessTypeId, city, country, region, hub, email, phone, website, googleRating, approvalStatus, isActive, isFeatured)
VALUES ('North Wind Cycles', 'north-wind-cycles', 'Premium road bike and e-bike hire in Mallorca with delivery and personalized setup.', 'North Wind Cycles offers expertly maintained premium road bikes and e-bikes for hire in Mallorca. They provide delivery and collection services, as well as personalized bike setup to ensure the perfect ride across the island''s legendary cycling routes.', 1, 2, 'Alaró', 'Spain', 'Mallorca', 'Alaró', 'hello@northwindcycles.com', '+34 635 471 871', 'https://www.northwindcycles.com/', '5.0', 'approved', true, false);

-- 3. The Doctrine Training Ltd. - Cycling Studio in Calgary
INSERT INTO businesses (name, slug, shortDescription, description, sportCategoryId, businessTypeId, city, country, region, hub, email, phone, website, googleRating, approvalStatus, isActive, isFeatured)
VALUES ('The Doctrine Training Ltd.', 'the-doctrine-training', 'Community of Calgary cyclists with coaching for all abilities and biking styles.', 'A community of local Calgary cyclists ranging in all abilities and experiences. Their coaches guide you to be a competent, skilled, and proficient cyclist regardless of your preferred biking style, from road cycling to mountain biking and gravel riding.', 1, 4, 'Calgary', 'Canada', 'Western Canada', 'Calgary', 'trev@thedoctrine.ca', '+1 403-831-8738', 'https://thedoctrine.ca/', '5.0', 'approved', true, false);

-- 4. Score Nutrition - Nutritionist in Calgary
INSERT INTO businesses (name, slug, shortDescription, description, sportCategoryId, businessTypeId, city, country, region, hub, email, phone, website, googleRating, approvalStatus, isActive, isFeatured)
VALUES ('Score Nutrition', 'score-nutrition', 'Sports nutrition coaching empowering athletes of all levels to achieve their next milestone.', 'Score Nutrition''s mission is to empower athletes of all ages and competitive levels to achieve their next milestone. Whether you''re training to crush your next race or just seeking better energy for your daily routine, they believe a healthy and uncomplicated approach to food is the key to success.', 2, 9, 'Calgary', 'Canada', 'Western Canada', 'Calgary', 'contact@scorenutrition.ca', '+1-403-990-4960', 'https://scorenutrition.ca/', '4.9', 'approved', true, false);

-- 5. Trail Run Adventures - Vacation Provider in Western US
INSERT INTO businesses (name, slug, shortDescription, description, sportCategoryId, businessTypeId, city, country, region, hub, email, phone, website, approvalStatus, isActive, isFeatured)
VALUES ('Trail Run Adventures', 'trail-run-adventures', 'Custom guided and unguided trail running trips for all levels of runners worldwide.', 'Trail Run Adventures offers custom-made guided and unguided trail running trips for all levels of runners, handling all the details such as activities, food, accommodations, and unforgettable running trails for once-in-a-lifetime adventures across spectacular mountain destinations.', 4, 15, 'Silverton', 'USA', 'Western US', 'Silverton', 'hello@trailrunadventures.com', '+1 972-835-6124', 'https://www.trailrunadventures.com', 'approved', true, false);

-- 6. Anna Frost Coaching - Coach in Western US
INSERT INTO businesses (name, slug, shortDescription, description, sportCategoryId, businessTypeId, city, country, region, hub, email, phone, website, approvalStatus, isActive, isFeatured)
VALUES ('Anna Frost Coaching', 'anna-frost-coaching', 'Personalized trail running coaching by ultra-runner Anna Frost with customized training programs.', 'Anna Frost Coaching offers personalized running coaching to help runners of all levels achieve their goals. They provide customized weekly training programs, goal setting advice, and race planning from one of the world''s most accomplished ultra-trail runners.', 2, 1, 'Silverton', 'USA', 'Western US', 'Silverton', 'hello@trailrunadventures.com', '+1 972-835-6124', 'https://www.trailrunadventures.com/coaching', 'approved', true, false);

-- 7. Personal Peak Coaching - Coach in Calgary
INSERT INTO businesses (name, slug, shortDescription, description, sportCategoryId, businessTypeId, city, country, region, hub, email, phone, website, approvalStatus, isActive, isFeatured)
VALUES ('Personal Peak Coaching', 'personal-peak-coaching', 'Exercise physiology and coaching specializing in optimizing training for endurance athletes.', 'Travis Brown is the Head Physiologist at Personal Peak. With a Masters of Kinesiology and certification as an Exercise Physiologist, he specializes in breaking down sports and optimizing training for runners, cyclists, and multi-sport athletes of all levels.', 2, 1, 'Calgary', 'Canada', 'Western Canada', 'Calgary', 'coaching@personalpeak.ca', '+1-430-991-7325', 'https://personalpeak.ca/trainer/travis-brown/', 'approved', true, false);

-- 8. CycloClaudia - Coach/Vacation Provider in Mallorca
INSERT INTO businesses (name, slug, shortDescription, description, sportCategoryId, businessTypeId, city, country, region, hub, email, phone, website, approvalStatus, isActive, isFeatured)
VALUES ('CycloClaudia', 'cycloclaudia', 'Personalized cycling coaching, guiding, and vacation experiences in Mallorca.', 'CycloClaudia, run by Claudia Striekwold, offers personalized cycling experiences and vacations in Mallorca. Whether you want to explore scenic routes or train specifically, she can create the perfect cycling holiday with expert coaching and local knowledge of the island''s best roads.', 1, 1, 'Alcudia', 'Spain', 'Mallorca', 'Alcudia', 'info@cycloclaudia.com', '+31 6 15895889', 'https://www.cycloclaudia.com/home', 'approved', true, false);

-- 9. Inspire Health & Performance - Physiotherapist in Calgary
INSERT INTO businesses (name, slug, shortDescription, description, sportCategoryId, businessTypeId, city, country, region, hub, email, phone, website, googleRating, approvalStatus, isActive, isFeatured)
VALUES ('Inspire Health & Performance', 'inspire-health-performance', 'Sports physiotherapy specializing in running and cycling injury treatment and performance.', 'Inspire Health & Performance offers performance physiotherapy services, specializing in running and cycling-related injuries and performance enhancement. Their team of experienced physiotherapists helps athletes recover faster and perform at their best.', 2, 7, 'Calgary', 'Canada', 'Western Canada', 'Calgary', 'booking@inspirehealthcalgary.ca', '+1-403-679-3977', 'https://www.inspirehealthcalgary.ca/', '5.0', 'approved', true, false);

